mapper.update:
UPDATE seal.retention_policy_version SET workflow_status = 'SUPERSEDED',
       updated_by = #{actorId}, updated_at = CURRENT_TIMESTAMP, version_no = version_no + 1
 WHERE retention_policy_id = #{retentionPolicyId}
   AND retention_policy_version_id <> #{approvedVersionId}
   AND workflow_status = 'APPROVED'

UPDATE seal.retention_policy SET current_approved_version_id = #{approvedVersionId},
       updated_by = #{actorId}, updated_at = CURRENT_TIMESTAMP, version_no = version_no + 1
 WHERE retention_policy_id = #{retentionPolicyId}
